      es: ["Longitud: 10 km", "Anchura: 2 km", "Red Natura 2000 desde 2004", "Punto más alto: 5 m s.n.m.", "Punto más bajo: 1 m bajo el nivel del mar", "Especie: Cigüeña negra (Ciconia nigra)"],
      pt: ["Comprimento: 10 km", "Largura: 2 km", "Área Natura 2000 desde 2004", "Ponto mais alto: 5 m acima do mar", "Ponto mais baixo: 1 m abaixo do mar", "Ave: Cegonha-preta"],
      fr: ["Longueur : 10 km", "Largeur : 2 km", "Zone Natura 2000 depuis 2004", "Point culminant : 5 m au-dessus du niveau de la mer", "Point bas : 1 m sous le niveau de la mer", "Oiseau : Cigogne noire"],
